def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate stats
    my_def = 0
    opp_def = 0
    cc = cd = dc = dd = 0
    for mine, opp in history:
        if mine == 'D':
            my_def += 1
        if opp == 'D':
            opp_def += 1
        if mine == 'C' and opp == 'C':
            cc += 1
        elif mine == 'C' and opp == 'D':
            cd += 1
        elif mine == 'D' and opp == 'C':
            dc += 1
        else:
            dd += 1

    opp_c = n - opp_def
    last_mine, last_opp = history[-1]

    # Recent window stats
    w = 12 if n >= 12 else n
    recent = history[n - w:]
    recent_opp_def = 0
    for _, o in recent:
        if o == 'D':
            recent_opp_def += 1
    recent_opp_c = w - recent_opp_def

    # Mirror score: does opponent copy our previous move?
    mirror_match = 0
    for i in range(1, n):
        if history[i][1] == history[i - 1][0]:
            mirror_match += 1
    mirror_rate = mirror_match / (n - 1) if n > 1 else 0.0

    # Consecutive opponent defections
    consec_opp_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_opp_def += 1
        else:
            break

    # Consecutive mutual defections
    dd_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_run += 1
        else:
            break

    # Consecutive mutual cooperations
    cc_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'C':
            cc_run += 1
        else:
            break

    remaining = 100 - n

    # Strongly cooperative: preserve mutual cooperation
    if opp_def == 0:
        # Defect only on the very last round to grab a bonus if safe
        if remaining == 0 and n >= 20:
            return 'D'
        return 'C'

    # Established mutual cooperation: keep it, minor end-game probing
    if cc_run >= 4 and recent_opp_c >= w - 1:
        if remaining <= 1 and n >= 20:
            return 'D'
        return 'C'

    # Long mutual defection lock: try to restart cooperation
    if dd_run >= 3:
        # Alternate between conciliatory and firm
        if dd_run % 2 == 1:
            return 'C'
        return 'D'

    # Opponent heavily defecting overall
    opp_def_rate = opp_def / n
    if opp_def_rate >= 0.75:
        # Defect mostly; rarely try cooperation to see if they soften
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Recent heavy defection by opponent
    if recent_opp_def >= w * 0.6 and recent_opp_def >= 4:
        # Firm retaliation, but with a forgiveness pulse
        if consec_opp_def == 1 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # If opponent mirrors us well, cooperate to sustain mutual C
    if mirror_rate >= 0.65 and n >= 6:
        # If we defected last, immediately repair
        if last_mine == 'D':
            return 'C'
        # Occasionally probe very late
        if remaining <= 1 and n >= 20 and rng.random() < 0.7:
            return 'D'
        return 'C'

    # Single recent opponent defection: retaliate once, then forgive
    if last_opp == 'D':
        if last_mine == 'D':
            # We already retaliated; try to restore cooperation
            if consec_opp_def >= 3:
                return 'D'
            return 'C'
        # They defected, we cooperated last
        if consec_opp_def >= 3:
            # Sustained defection warrants firm response
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        # Single defection: retaliate with probability, but forgive often
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # Opponent cooperated last
    # If we defected last, repair immediately
    if last_mine == 'D':
        return 'C'

    # Exploitation detection: opponent defected multiple times after our C
    if cd >= 2 and dc <= 1 and opp_def_rate < 0.4:
        # They repeatedly exploit; become more firm
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # End-game exploitation when we're behind and opponent is ok-ish
    if remaining <= 1 and n >= 20 and opp_def_rate < 0.3:
        return 'D'

    # Default: cooperate
    return 'C'
